export const totalPlanned = 50;

export const lockedCount = executives.filter((e) => e.status === 'locked').length;
export const draftedCount = executives.filter((e) => e.status !== 'candidate').length;
export const illustratedCount = executives.filter((e) => Boolean(e.front)).length;

export const featuredExecutives = executives.filter((e) => e.status === 'locked').slice(0, 6);

export function getExecutive(slug: string) {
  return executives.find((e) => e.slug === slug);
}

export type PortraitCredit = {
  credit: string;
  license: string;
  licenseUrl?: string;
  sourceUrl?: string;
};

type RefRow = { slug: string; ref?: (PortraitCredit & { url?: string }) | null };

/**
 * Photographer credits, written by scripts/ceo-refs.mjs. Same likeness rule as
 * Series Three, Four and Five: painted from an identified photograph, or no face at all.
 */
import refs from '../../data/ceo-references.json' with { type: 'json' };

export function getPortraitCredit(slug: string): PortraitCredit | undefined {
  const row = (refs as RefRow[]).find((r) => r.slug === slug);
  if (!row?.ref) return undefined;
  const { credit, license, licenseUrl, sourceUrl } = row.ref;
  return { credit, license, licenseUrl, sourceUrl };
}
